package io.onemsg.sdk.core

import io.circe.Json

/** Helpers for form-urlencoded bodies generated by scala-sttp. */
object FormSupport {
  def fromMap(entries: (String, Any)*): Map[String, String] =
    entries.flatMap {
      case (_, null)  => None
      case (_, None)  => None
      case (k, Some(v)) => Some(k -> stringify(v))
      case (k, v)     => Some(k -> stringify(v))
    }.toMap

  private def stringify(value: Any): String =
    value match {
      case j: Json                                        => j.noSpaces
      case s: String                                      => s
      case h: io.onemsg.sdk.model.SendFlowRequestHeader  => h.value.noSpaces
      case h: io.onemsg.sdk.model.SendFlowRequest1Header => h.value.noSpaces
      case other                                          => other.toString
    }

  def jsonSeq(values: Seq[Any]): String =
    Json.fromValues(values.map(toJson)).noSpaces

  private def toJson(value: Any): Json =
    value match {
      case j: Json       => j
      case s: String     => Json.fromString(s)
      case n: Int        => Json.fromInt(n)
      case n: Long       => Json.fromLong(n)
      case n: Double     => Json.fromDoubleOrNull(n)
      case n: Boolean    => Json.fromBoolean(n)
      case m: Map[_, _]  =>
        Json.obj(m.toSeq.map { case (key, item) => key.toString -> toJson(item) }: _*)
      case items: Seq[_] => Json.fromValues(items.map(toJson))
      case other         => Json.fromString(other.toString)
    }
}
